   export interface RunPaths {
     readonly root: string;
     readonly specs: string;
     readonly pipeline: string;
     readonly state: string;
     readonly ledger: string;
     readonly pausedDir: string;
     readonly request: string;
     readonly log: string;
   }
   export const runPaths = (profileFile: string, branch: string): RunPaths => {
     const { profile, root } = loadProjectProfileFile(profileFile);
     const { specs, pipeline } = resolveProfilePaths(profile, { root, branch });
     return {
       root,
       specs,
       pipeline,
       state: path.join(pipeline, STATE_FILENAME),
       ledger: path.join(pipeline, LEDGER_FILENAME),
       pausedDir: path.join(pipeline, PAUSE_DIRNAME),
       request: path.join(pipeline, 'request.txt'),
       log: path.join(pipeline, 'dpf.log'),
     };
   };
