1	import { z } from 'zod';
2	
3	import { addIssues, duplicatesOf, IsoDate, namesADirectory, NonEmpty } from './common.js';
4	import { SchemaVersionSchema } from './version.js';
5	
6	/**
7	 * SPEC-A output: the goal set, and the noun -> surface resolution plus the drift table
8	 * that the current-state document is rendered from.
9	 */
10	
11	const GOAL_ID_PATTERN = /^G-\d+$/u;
12	const NON_GOAL_ID_PATTERN = /^NG-\d+$/u;
13	
14	export const GoalEntrySchema = z
15	  .strictObject({ id: z.string().regex(GOAL_ID_PATTERN), text: z.string().min(1), source: z.string().min(1) })
16	  .readonly();
17	
18	export const NonGoalEntrySchema = z
19	  .strictObject({ id: z.string().regex(NON_GOAL_ID_PATTERN), text: z.string().min(1), source: z.string().min(1) })
20	  .readonly();
21	
22	const goalSetFields = {
23	  goals: z.array(GoalEntrySchema).min(1).readonly(),
24	  nonGoals: z.array(NonGoalEntrySchema).readonly(),
25	};
26	
27	interface GoalSetLike {
28	  readonly goals: readonly { readonly id: string }[];
29	  readonly nonGoals: readonly { readonly id: string }[];
30	}
31	
32	/** Ids are the citation keys of every requirement, so they are unique across the WHOLE document. */
33	const duplicateIdMessages = (set: GoalSetLike): readonly string[] =>
34	  duplicatesOf([...set.goals, ...set.nonGoals].map(entry => entry.id)).map(id => `id "${id}" is used more than once`);
35	
36	const refineUniqueIds = (set: GoalSetLike, ctx: z.core.$RefinementCtx<unknown>): void =>
37	  addIssues(ctx, ['goals'], duplicateIdMessages(set));
38	
39	export const GoalSetSchema = z.strictObject(goalSetFields).superRefine(refineUniqueIds);
40	
41	export const GoalsDocSchema = z.strictObject({ schemaVersion: SchemaVersionSchema, ...goalSetFields }).superRefine(refineUniqueIds);
42	
43	export const SHAPE_KINDS = ['feature', 'modification', 'bug', 'refactor'] as const;
44	export const SURFACE_KINDS = ['feature', 'module', 'entry-point', 'unknown'] as const;
45	
46	/**
47	 * Exactly the status vocabulary the current-state lint gate accepts. Widening it here would
48	 * produce a document that only fails later, at the gate, with no stage-local feedback.
49	 */
50	export const DRIFT_STATUSES = ['matches', 'drift', 'bug', 'unclear', 'new', 'broken'] as const;
51	
52	/** The statuses whose claim is unverifiable without prose - the gate's MISSING_NOTES rule. */
53	const NOTES_REQUIRED_STATUSES: readonly string[] = ['matches', 'bug', 'broken', 'unclear'];
54	
55	/**
56	 * The kinds that name ONE surface a reader can open. `feature` is absent because a feature
57	 * legitimately IS a directory, and `unknown` because it is the honest "resolved to nothing".
58	 */
59	const FILE_GRAINED_KINDS: readonly string[] = ['module', 'entry-point'];
60	
61	interface MappingLike {
62	  readonly noun: string;
63	  readonly surfaceId: string | null;
64	  readonly kind: string;
65	  readonly path: string | null;
66	}
67	
68	const directoryFieldsOf = (entry: MappingLike): readonly (readonly [string, string])[] => {
69	  const fields: readonly (readonly [string, string | null])[] = [
70	    ['surfaceId', entry.surfaceId],
71	    ['path', entry.path],
72	  ];
73	  return fields.filter((pair): pair is readonly [string, string] => pair[1] !== null && namesADirectory(pair[1]));
74	};
75	
76	const grainMessage = (entry: MappingLike, field: string, value: string): string =>
77	  `noun "${entry.noun}": ${field} "${value}" names a directory, but kind "${entry.kind}" is file-grained - ` +
78	  `name the specific file this row touches (the row's own evidence usually cites one), or use ` +
79	  `kind: "feature" when the surface really is a directory, or null when it is unknown`;
80	
81	/**
82	 * The same rule `spec-fill` applies to a touched-snapshot row, applied where the value is
83	 * PRODUCED: `surfaceId` becomes the outline stage's ref vocabulary, so a directory admitted
84	 * here is a legal enum member two stages on and only fails at the fill stage, with no
85	 * stage-local feedback - the reasoning DRIFT_STATUSES above already states. Both stages share
86	 * `namesADirectory` so "what is a directory" agrees by construction, not by two copies.
87	 */
88	export const refineMappingGrain = (entry: MappingLike, ctx: z.core.$RefinementCtx<unknown>): void => {
89	  if (!FILE_GRAINED_KINDS.includes(entry.kind)) return;
90	  directoryFieldsOf(entry).forEach(([field, value]) => addIssues(ctx, [field], [grainMessage(entry, field, value)]));
91	};
92	
93	export const MappingEntrySchema = z
94	  .strictObject({
95	    noun: z.string().min(1),
96	    surfaceId: z.string().min(1).nullable(),
97	    kind: z.enum(SURFACE_KINDS),
98	    path: z.string().min(1).nullable(),
99	    evidence: z.string().min(1),
100	  })
101	  .superRefine(refineMappingGrain);
102	
103	export const DriftEntrySchema = z.strictObject({
104	  id: z.string().min(1),
105	  snapshotSays: z.string().min(1),
106	  codeSays: z.string().min(1),
107	  status: z.enum(DRIFT_STATUSES),
108	  notes: z.string().nullable(),
109	});
110	
111	interface ResolutionLike {
112	  readonly mapping: readonly { readonly noun: string; readonly surfaceId: string | null; readonly kind: string }[];
113	  readonly drift: readonly { readonly id: string; readonly status: string; readonly notes: string | null }[];
114	}
115	
116	const notesMessages = (doc: ResolutionLike): readonly string[] =>
117	  doc.drift
118	    .filter(row => NOTES_REQUIRED_STATUSES.includes(row.status) && (row.notes ?? '').trim() === '')
119	    .map(row => `row "${row.id}": status "${row.status}" requires non-empty notes`);
120	
121	const unresolvedKindMessages = (doc: ResolutionLike): readonly string[] =>
122	  doc.mapping
123	    .filter(entry => entry.surfaceId === null && entry.kind !== 'unknown')
124	    .map(entry => `noun "${entry.noun}": resolved to no surface, so kind MUST be "unknown"`);
125	
126	/**
127	 * Both rules are the rendering gate's rules, enforced at authoring time: the rendered
128	 * current-state document then passes its lint by construction instead of failing a gate
129	 * one stage later, where the model has already lost the context that produced the row.
130	 */
131	const refineResolution = (doc: ResolutionLike, ctx: z.core.$RefinementCtx<unknown>): void => {
132	  addIssues(ctx, ['drift'], notesMessages(doc));
133	  addIssues(ctx, ['mapping'], unresolvedKindMessages(doc));
134	};
135	
136	export const ResolutionDocSchema = z
137	  .strictObject({
138	    schemaVersion: SchemaVersionSchema,
139	    shape: z.enum(SHAPE_KINDS),
140	    mapping: z.array(MappingEntrySchema).min(1).readonly(),
141	    drift: z.array(DriftEntrySchema).readonly(),
142	    blastRadius: z.array(z.string().min(1)).readonly(),
143	  })
144	  .superRefine(refineResolution);
145	
146	/**
147	 * The persisted resolution document: the model's output plus the emit clock and branch its
148	 * current-state.md rendered from, so re-rendering the same file never needs a second `now()` or
149	 * a look-up of the scope.
150	 */
151	export const ResolutionIrSchema = ResolutionDocSchema.safeExtend({ generatedAt: IsoDate, branch: NonEmpty });
152	
153	/**
154	 * The legacy `resolution.json` the `/dpf.specify` command writes: one entry per resolved
155	 * request phrase, BEFORE the pipeline's structured resolution document exists. Non-strict on
156	 * purpose - the command persists extra fields into the same file (the freshness gate's
157	 * `freshnessDecision`), and a legacy reader must not refuse the document over them.
158	 */
159	const LegacyResolutionEntrySchema = z.object({
160	  request_phrase: z.string(),
161	  pick: z.string(),
162	  candidates: z.array(z.string()),
163	  confidence: z.number().min(0).max(1),
164	  rationale: z.string(),
165	});
166	
167	export const LegacyResolutionSchema = z.object({
168	  resolved: z.array(LegacyResolutionEntrySchema),
169	});
170	
171	export type GoalEntry = Readonly<z.infer<typeof GoalEntrySchema>>;
172	export type NonGoalEntry = Readonly<z.infer<typeof NonGoalEntrySchema>>;
173	export type GoalSet = Readonly<z.infer<typeof GoalSetSchema>>;
174	export type GoalsDoc = Readonly<z.infer<typeof GoalsDocSchema>>;
175	export type DriftStatus = (typeof DRIFT_STATUSES)[number];
176	export type ResolutionDoc = Readonly<z.infer<typeof ResolutionDocSchema>>;
177	export type ResolutionIr = Readonly<z.infer<typeof ResolutionIrSchema>>;
178	export type LegacyResolution = Readonly<z.infer<typeof LegacyResolutionSchema>>;
