import { closeSync, fsyncSync, openSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { isRecord } from './common.js';
import { jsonPath, type JsonPathSegment } from './path.js';
import { IR_KINDS, type IrKind, type IrOf, type IrSpec } from './registry.js';

/** The origin an ok:false parse names when no file was given. */
const TEXT_ORIGIN = '<text>';

/** The path of an issue at the whole document. */
const ROOT_PATH = '$';

/** The field an array element must carry to be spellable in `[id=...]` form. */
const ID_KEY = 'id';

/** The repo's IR byte form: two-space indent. */
const JSON_INDENT = 2;

export type IrIssue = { readonly path: string; readonly message: string };

export type IrResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly file: string; readonly issues: readonly IrIssue[] };

/** The marker a failed JSON parse or file read returns - distinct from every parsed value. */
const INVALID: unique symbol = Symbol('invalid');

const tryJson = (text: string): unknown => {
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return INVALID;
  }
};

const tryRead = (file: string): string | typeof INVALID => {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return INVALID;
  }
};

const rootIssues = (message: string): readonly IrIssue[] => [{ path: ROOT_PATH, message }];

/** The shape every zod issue carries; an `unrecognized_keys` issue adds the keys it refused. */
interface ZodIssueLike {
  readonly code: string;
  readonly path: readonly PropertyKey[];
  readonly message: string;
  /** Present only on `unrecognized_keys` issues: the keys the object refused. */
  readonly keys?: readonly string[];
}

/**
 * An `unrecognized_keys` issue is spelled at the key itself — that is where the unknown field
 * lives, and the path a reader can point at — not only in the message.
 */
const pathsOf = (raw: unknown, issue: ZodIssueLike): readonly string[] => {
  const base = issuePath(raw, issue.path);
  return issue.code === 'unrecognized_keys' && issue.keys !== undefined
    ? issue.keys.map(key => `${base}.${key}`)
    : [base];
};

/** The IrIssue form of a zod rejection: one line per refused key, each naming its own path. */
export const irIssues = (raw: unknown, issues: readonly ZodIssueLike[]): readonly IrIssue[] =>
  issues.flatMap(issue => pathsOf(raw, issue).map(path => ({ path, message: issue.message })));

const childOf = (container: unknown, key: PropertyKey): unknown =>
  Array.isArray(container)
    ? container[typeof key === 'number' ? key : Number(key)]
    : isRecord(container)
      ? container[String(key)]
      : undefined;

/** An index into an element that carries a string `id` is spelled `[id=...]`, else `[n]`. */
const indexSegment = (container: unknown, index: number): JsonPathSegment => {
  const child = childOf(container, index);
  const id = isRecord(child) ? child[ID_KEY] : undefined;
  return typeof id === 'string' ? { id } : index;
};

/** One step of an issue path; a non-numeric key - and a symbol, which no zod path carries - is spelled `.key`. */
const segmentOf = (container: unknown, key: PropertyKey): JsonPathSegment =>
  typeof key === 'number' ? indexSegment(container, key) : String(key);

interface PathWalk {
  readonly container: unknown;
  readonly segs: readonly JsonPathSegment[];
}

/**
 * A zod issue path, spelled as an IR path: `$` plus one `.key` / `[n]` / `[id=...]` per step,
 * walking the parsed value alongside so an index takes the id form its element earns. Every
 * output round-trips through `parsePath` while each key matches the grammar's key set
 * (`[A-Za-z0-9_$-]`) and no id carries `]`; a record key outside that set - e.g. a dimension
 * name with a space - is spelled verbatim, and `parsePath` refuses it.
 */
export const issuePath = (raw: unknown, path: readonly PropertyKey[]): string =>
  jsonPath(
    ...path.reduce<PathWalk>(
      (acc, key) => ({ container: childOf(acc.container, key), segs: [...acc.segs, segmentOf(acc.container, key)] }),
      { container: raw, segs: [] }
    ).segs
  );

/**
 * Parse IR text against a spec. NEVER throws: bad JSON lands as a single `$` issue and schema
 * failures are mapped one by one. `spec.migrate` runs on the raw value BEFORE the schema.
 */
export const parseIrWith = (spec: IrSpec, text: string, file?: string): IrResult<unknown> => {
  const origin = file ?? TEXT_ORIGIN;
  const raw = tryJson(text);
  if (raw === INVALID) return { ok: false, file: origin, issues: rootIssues('invalid JSON') };
  const value = spec.migrate === undefined ? raw : spec.migrate(raw);
  const parsed = spec.schema.safeParse(value);
  return parsed.success
    ? { ok: true, value: parsed.data }
    : {
        ok: false,
        file: origin,
        issues: irIssues(value, parsed.error.issues),
      };
};

/**
 * Serialize a value to IR bytes: validate FIRST - a schema failure is a programming error and
 * throws - then the repo byte form, two-space indent plus a trailing newline.
 */
export const serializeIrWith = (spec: IrSpec, value: unknown): string => {
  spec.schema.parse(value);
  return `${JSON.stringify(value, null, JSON_INDENT)}\n`;
};

/** Read and parse an IR file. A missing or unreadable file is a `$`-issue result, not a throw. */
export const readIrWith = (spec: IrSpec, file: string): IrResult<unknown> => {
  const text = tryRead(file);
  return text === INVALID ? { ok: false, file, issues: rootIssues('file is missing or unreadable') } : parseIrWith(spec, text, file);
};

/** Fsync a file or its directory so a rename is durable: the temp file and the directory it lands in. */
const fsyncPath = (target: string): void => {
  const fd = openSync(target, 'r');
  try {
    fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
};

/**
 * Write IR bytes atomically and durably: serialize FIRST, so an invalid value throws before any
 * filesystem write; then a `${file}.tmp-<pid>` sibling is fsynced and renamed onto `file`, and
 * its directory is fsynced so the rename survives a crash; no tmp file survives a failure.
 */
export const writeIrAtomicWith = (spec: IrSpec, file: string, value: unknown): void => {
  const bytes = serializeIrWith(spec, value);
  const tmp = `${file}.tmp-${process.pid}`;
  try {
    writeFileSync(tmp, bytes);
    fsyncPath(tmp);
    renameSync(tmp, file);
    fsyncPath(path.dirname(file));
  } catch (error) {
    rmSync(tmp, { force: true });
    throw error;
  }
};

/** The kind's schema accepted the value, so the result carries that kind's document type (the one cast of the module). */
const asKind = <K extends IrKind>(result: IrResult<unknown>): IrResult<IrOf<K>> => result as IrResult<IrOf<K>>;

/** Parse IR text for a registered kind. */
export const parseIr = <K extends IrKind>(kind: K, text: string): IrResult<IrOf<K>> => asKind<K>(parseIrWith(IR_KINDS[kind], text));

/** Read and parse an IR file for a registered kind. */
export const readIr = <K extends IrKind>(kind: K, file: string): IrResult<IrOf<K>> => asKind<K>(readIrWith(IR_KINDS[kind], file));

/** Serialize for a registered kind; a schema failure is a programming error and throws. */
export const serializeIr = <K extends IrKind>(kind: K, value: IrOf<K>): string => serializeIrWith(IR_KINDS[kind], value);

/** Atomic write for a registered kind; a schema failure throws before any filesystem write. */
export const writeIrAtomic = <K extends IrKind>(kind: K, file: string, value: IrOf<K>): void =>
  writeIrAtomicWith(IR_KINDS[kind], file, value);

