19	const TRAILING_PUNCTUATION_RE = /[.,;:!?)]+$/u;
20	/** A ref glued to `(` is a decorator call (`@app.route(…)`, `@Injectable()`), not a document. */
21	const CALL_OPEN = '(';
22	/** A document names a file with an extension: `@tanstack/react-query`, `@types/node` and a dir name none. */
23	const DOC_FILE_RE = /\.[\p{L}\p{N}_-]+$/u;
24	
25	/** The section's caps under a total of `totalTokens`: one document never gets more than the total. */
26	interface DocCaps {
27	  readonly doc: StanzaCap;
28	  readonly totalChars: number;
29	  readonly overLead: string;
30	}
31	
32	const docCaps = (totalTokens: number): DocCaps => {
33	  const docTokens = Math.min(DEFAULT_REQUEST_DOC_TOKENS, totalTokens);
34	  return {
35	    doc: { chars: docTokens * CHARS_PER_TOKEN, name: `${String(docTokens)}-token request-document cap` },
36	    totalChars: totalTokens * CHARS_PER_TOKEN,
37	    overLead: `left out (over the ${String(totalTokens)}-token request-documents total cap): `,
38	  };
39	};
40	
41	const REFUSED_LEAD = 'refused (outside the project root): ';
42	const HIDDEN_LEAD = 'refused (hidden file): ';
43	/** The file surface reads every failure as empty text: absent, empty, unreadable and a directory look alike. */
44	const NO_CONTENT_LEAD = 'no content (missing, empty or unreadable): ';
45	const NOT_A_FILE_LEAD = 'not read (names no file — a document ref carries its extension): ';
46	
47	const notACall = (text: string, match: RegExpMatchArray): boolean =>
48	  text[(match.index ?? 0) + match[0].length] !== CALL_OPEN;
49	
50	/** The refs in request order, each once — a ref that names no file included, so its drop is rendered. */
51	export const requestDocRefs = (text: string): readonly string[] => [
52	  ...new Set(
53	    [...text.matchAll(REF_RE)]
54	      .filter(match => notACall(text, match))
55	      .map(match => (match[1] ?? '').replaceAll('\\', '/').replace(TRAILING_PUNCTUATION_RE, ''))
56	      .filter(ref => ref.length > 0)
57	  ),
58	];
59	
60	const insideRoot = (ref: string): boolean => !path.isAbsolute(ref) && !ref.split('/').includes('..');
61	
62	/** A dotfile (`.env`, `.npmrc`) holds settings or secrets, never a document the request hands over. */
63	const hidden = (ref: string): boolean => path.posix.basename(ref).startsWith('.');
64	
65	const namesFile = (ref: string): boolean => DOC_FILE_RE.test(ref);
66	
67	/** Each ref lands in exactly one outcome: refused, hidden, not a file, or read. */
68	const refusedRef = (ref: string): boolean => !insideRoot(ref);
69	const hiddenRef = (ref: string): boolean => insideRoot(ref) && hidden(ref);
70	const notAFileRef = (ref: string): boolean => insideRoot(ref) && !hidden(ref) && !namesFile(ref);
71	const readableRef = (ref: string): boolean => insideRoot(ref) && !hidden(ref) && namesFile(ref);
72	
73	interface ReadDoc {
74	  readonly ref: string;
75	  readonly content: string;
76	}
77	
78	const leadLine = (lead: string, refs: readonly string[]): readonly string[] =>
79	  refs.length === 0 ? [] : [`${lead}${refs.join(', ')}`];
80	
81	interface Packed {
82	  readonly lines: readonly string[];
83	  readonly chars: number;
84	  readonly over: readonly string[];
85	}
86	
87	/** In request order, each doc costs what its own cap lets it show; one that would pass the total is named, not shown. */
88	const pack = (docs: readonly ReadDoc[], caps: DocCaps): Packed =>
89	  docs.reduce<Packed>(
90	    (packed, doc) => {
91	      const chars = packed.chars + Math.min(doc.content.length, caps.doc.chars);
92	      return chars > caps.totalChars
93	        ? { ...packed, over: [...packed.over, doc.ref] }
94	        : { lines: [...packed.lines, ...numberedStanza(doc.ref, doc.content, caps.doc)], chars, over: packed.over };
95	    },
96	    { lines: [], chars: 0, over: [] }
97	  );
98	
99	/** `totalTokens` is `budgets.requestDocTokens`; absent keeps `DEFAULT_REQUEST_DOCS_TOTAL_TOKENS`. */
100	export const requestDocLines = async (
101	  files: FileSurface,
102	  refs: readonly string[],
103	  totalTokens: number = DEFAULT_REQUEST_DOCS_TOTAL_TOKENS
104	): Promise<readonly string[]> => {
105	  const caps = docCaps(totalTokens);
106	  const docs: readonly ReadDoc[] = await Promise.all(
107	    refs.filter(readableRef).map(async ref => ({ ref, content: await files.read(ref) }))
108	  );
109	  const packed = pack(docs.filter(doc => doc.content.length > 0), caps);
110	  return [
111	    ...packed.lines,
112	    ...leadLine(caps.overLead, packed.over),
113	    ...leadLine(REFUSED_LEAD, refs.filter(refusedRef)),
114	    ...leadLine(HIDDEN_LEAD, refs.filter(hiddenRef)),
115	    ...leadLine(NO_CONTENT_LEAD, docs.filter(doc => doc.content.length === 0).map(doc => doc.ref)),
116	    ...leadLine(NOT_A_FILE_LEAD, refs.filter(notAFileRef)),
117	  ];
118	};
