===COMMON
import { z } from 'zod';

import { parsePath } from './path.js';

/** Pieces every IR document schema shares: shared field schemas, issue formatting, duplicate detection, the surface-name rule. */

/** A string that must carry content - the empty string is never a value in an IR document. */
export const NonEmpty = z.string().min(1);

/**
 * A root-relative path into the feature dir: never absolute, and no `..` segment that could
 * escape it. The reader resolves it against the dir the document lives in.
===VERSION
import { z } from 'zod';

/** The one owner of the schema-version literal; writers stamp their envelopes with it. */
export const IR_SCHEMA_VERSION = 1;

/** Every IR document is versioned so a replayed capture can never be parsed by a newer contract. */
export const SchemaVersionSchema = z.literal(IR_SCHEMA_VERSION);
===PATH
/**
 * The IR path grammar, deliberately tiny: `$` root, `.key`, `[n]` array index, `[id=<value>]`
 * array element whose `id` field equals `<value>`.
 *
 * Both array forms exist because they fail differently. A reviser that miscounts an index
 * silently patches the WRONG requirement and nothing detects it; an `[id=...]` selector is
 * checkable — it either matches exactly one row or it errors. Emitters SHOULD emit the id
 * form; the index form stays for insert positions and for arrays whose rows carry no id.

