import path from 'node:path';

import type { FileSurface } from '../knowledge/index.js';
import { numberedStanza, type StanzaCap } from './excerpts.js';
import { CHARS_PER_TOKEN } from './tokens.js';
import { DEFAULT_REQUEST_DOC_TOKENS, DEFAULT_REQUEST_DOCS_TOTAL_TOKENS } from './types.js';

/**
 * F-12. The `request-docs` section: the documents the request names with `@path`. The 052 request
 * said "read @docs/…/next-features-roadmap.md", the file existed, and every resolution mapping
 * still read "not present in the evidence" - the bundle carried code excerpts only, cut at 1k
 * tokens, and the roadmap items sat past that cut. A named document is read whole up to its own
 * cap. A ref that leaves the project root is refused and the refusal is rendered: loud, never a
 * silent drop, and never a read outside the tree.
 */

/** `@` not glued to a word (so `me@example.com` is no ref), then a path in any script, `/` or `\` separated. */
const REF_RE = /(?<![\p{L}\p{N}_@])@([\p{L}\p{N}_.\-/\\]+)/gu;
const TRAILING_PUNCTUATION_RE = /[.,;:!?)]+$/u;
/** A ref glued to `(` is a decorator call (`@app.route(…)`, `@Injectable()`), not a document. */
const CALL_OPEN = '(';
/** A document names a file with an extension: `@tanstack/react-query`, `@types/node` and a dir name none. */
const DOC_FILE_RE = /\.[\p{L}\p{N}_-]+$/u;

/** The section's caps under a total of `totalTokens`: one document never gets more than the total. */
interface DocCaps {
  readonly doc: StanzaCap;
  readonly totalChars: number;
  readonly overLead: string;
}

const docCaps = (totalTokens: number): DocCaps => {
  const docTokens = Math.min(DEFAULT_REQUEST_DOC_TOKENS, totalTokens);
  return {
    doc: { chars: docTokens * CHARS_PER_TOKEN, name: `${String(docTokens)}-token request-document cap` },
    totalChars: totalTokens * CHARS_PER_TOKEN,
    overLead: `left out (over the ${String(totalTokens)}-token request-documents total cap): `,
  };
};

const REFUSED_LEAD = 'refused (outside the project root): ';
const HIDDEN_LEAD = 'refused (hidden file): ';
/** The file surface reads every failure as empty text: absent, empty, unreadable and a directory look alike. */
const NO_CONTENT_LEAD = 'no content (missing, empty or unreadable): ';
const NOT_A_FILE_LEAD = 'not read (names no file — a document ref carries its extension): ';

const notACall = (text: string, match: RegExpMatchArray): boolean =>
  text[(match.index ?? 0) + match[0].length] !== CALL_OPEN;

/** The refs in request order, each once — a ref that names no file included, so its drop is rendered. */
export const requestDocRefs = (text: string): readonly string[] => [
  ...new Set(
    [...text.matchAll(REF_RE)]
      .filter(match => notACall(text, match))
      .map(match => (match[1] ?? '').replaceAll('\\', '/').replace(TRAILING_PUNCTUATION_RE, ''))
      .filter(ref => ref.length > 0)
  ),
];

const insideRoot = (ref: string): boolean => !path.isAbsolute(ref) && !ref.split('/').includes('..');

/** A dotfile (`.env`, `.npmrc`) holds settings or secrets, never a document the request hands over. */
const hidden = (ref: string): boolean => path.posix.basename(ref).startsWith('.');

const namesFile = (ref: string): boolean => DOC_FILE_RE.test(ref);

/** Each ref lands in exactly one outcome: refused, hidden, not a file, or read. */
const refusedRef = (ref: string): boolean => !insideRoot(ref);
const hiddenRef = (ref: string): boolean => insideRoot(ref) && hidden(ref);
const notAFileRef = (ref: string): boolean => insideRoot(ref) && !hidden(ref) && !namesFile(ref);
const readableRef = (ref: string): boolean => insideRoot(ref) && !hidden(ref) && namesFile(ref);

interface ReadDoc {
  readonly ref: string;
  readonly content: string;
}

const leadLine = (lead: string, refs: readonly string[]): readonly string[] =>
  refs.length === 0 ? [] : [`${lead}${refs.join(', ')}`];

interface Packed {
  readonly lines: readonly string[];
  readonly chars: number;
  readonly over: readonly string[];
}

/** In request order, each doc costs what its own cap lets it show; one that would pass the total is named, not shown. */
const pack = (docs: readonly ReadDoc[], caps: DocCaps): Packed =>
  docs.reduce<Packed>(
    (packed, doc) => {
      const chars = packed.chars + Math.min(doc.content.length, caps.doc.chars);
      return chars > caps.totalChars
        ? { ...packed, over: [...packed.over, doc.ref] }
        : { lines: [...packed.lines, ...numberedStanza(doc.ref, doc.content, caps.doc)], chars, over: packed.over };
    },
    { lines: [], chars: 0, over: [] }
  );

/** `totalTokens` is `budgets.requestDocTokens`; absent keeps `DEFAULT_REQUEST_DOCS_TOTAL_TOKENS`. */
export const requestDocLines = async (
  files: FileSurface,
  refs: readonly string[],
  totalTokens: number = DEFAULT_REQUEST_DOCS_TOTAL_TOKENS
): Promise<readonly string[]> => {
  const caps = docCaps(totalTokens);
  const docs: readonly ReadDoc[] = await Promise.all(
    refs.filter(readableRef).map(async ref => ({ ref, content: await files.read(ref) }))
  );
  const packed = pack(docs.filter(doc => doc.content.length > 0), caps);
  return [
    ...packed.lines,
    ...leadLine(caps.overLead, packed.over),
    ...leadLine(REFUSED_LEAD, refs.filter(refusedRef)),
    ...leadLine(HIDDEN_LEAD, refs.filter(hiddenRef)),
    ...leadLine(NO_CONTENT_LEAD, docs.filter(doc => doc.content.length === 0).map(doc => doc.ref)),
    ...leadLine(NOT_A_FILE_LEAD, refs.filter(notAFileRef)),
  ];
};

import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import type { StepType } from '../contracts/index.js';
import type { GateDrop } from './capability.js';

/**
 * The seam Waves 1-2 fill. The driver does not call a model: it materializes the
 * step's fully resolved inputs to disk and stops. `--resume` picks the run back up
 * from the outputs the step declares.
 */

export const PAUSE_DIRNAME = 'paused';

export interface PausePayload {
  readonly runId: string;
  readonly runFingerprint: string;
  /** The composed prompt epoch (P6/A12); present only once a composer supplies one. */
  readonly epochId: string | undefined;
  readonly stepId: string;
  readonly stepType: StepType;
  readonly role: string | undefined;
  /** The model profile the role maps to, from `spec-pipeline.config.json`. */
  readonly modelProfile: string | undefined;
  readonly outputSchemaRef: string | undefined;
  readonly inputs: Readonly<Record<string, string>>;
  readonly outputs: readonly string[];
  readonly critics: readonly string[] | undefined;
  readonly reviser: string | undefined;
  readonly maxRounds: number | undefined;
  readonly gatesEachRound: readonly string[] | undefined;
  readonly droppedGates: readonly GateDrop[] | undefined;
  /** Why the stage could not close itself: the last attempt's errors, verbatim. */
  readonly validationErrors?: readonly string[];
  /**
   * W3-05. A human target a gate re-enters: the gate's findings file, so the harness names it
   * and the operator fixes the IR with `spec-pipeline ir set/patch`. Absent is no repair.
   */
  readonly repairFindings?: string;
}

export const writePausePayload = (pipelineDir: string, payload: PausePayload): string => {
  const directory = path.join(pipelineDir, PAUSE_DIRNAME);
  mkdirSync(directory, { recursive: true });
  const file = path.join(directory, `${payload.stepId}.json`);
  writeFileSync(file, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  return file;
};

export const describePause = (payload: PausePayload): string =>
  [
    `${payload.stepType} step would receive`,
    `${Object.keys(payload.inputs).length} input(s)`,
    `-> ${payload.outputs.length} declared output(s)`,
  ].join(' ');

